      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>

      <form [formGroup]="localeForm" (ngSubmit)="saveLocale()" aria-label="Choose your locale">
        <p>Locale: <strong data-testid="user-locale-current">{{ session.locale() }}</strong></p>
        <label for="user-locale">Show figures as</label>
        <select id="user-locale" data-testid="user-locale" formControlName="locale">
          @for (l of locales; track l) {
            <option [value]="l">{{ l }}</option>
          }
        </select>
        <button type="submit" data-testid="user-locale-save" [disabled]="savingLocale()">Save locale</button>
        @if (localeError(); as err) {
          <p role="alert" data-testid="user-locale-error">{{ err }}</p>
        }
      </form>

      <form [formGroup]="sheetForm" (ngSubmit)="loadSheet()" aria-label="Load a sheet">
        <label for="sheet-id">Sheet id</label>
        <input id="sheet-id" data-testid="sheet-id-input" formControlName="id" autocomplete="off" />
        <button type="submit" data-testid="sheet-load" [disabled]="loading()">Load</button>
        @if (sheetError(); as err) {
          <p role="alert" data-testid="sheet-load-error">{{ err }}</p>
        }
      </form>

      @if (sheets.current(); as sheet) {
        <p>Sheet: <strong data-testid="sheet-current-id">{{ sheet.id }}</strong></p>
        <p>Today: <strong data-testid="sheet-today">{{ sheet.today }}</strong></p>
        <p>
          Archived: <strong data-testid="sheet-archived">{{ sheet.archived ? 'yes' : 'no' }}</strong>
          <button type="button" data-testid="sheet-archive" [disabled]="archiving()" (click)="archive()">Archive sheet</button>
        </p>

        <form [formGroup]="cloneForm" (ngSubmit)="cloneSheet()" aria-label="Clone the sheet to another id">
          <label for="sheet-clone-to">Clone to sheet id</label>
          <input id="sheet-clone-to" data-testid="sheet-clone-to" formControlName="to" autocomplete="off" />
          <button type="submit" data-testid="sheet-clone" [disabled]="cloning()">Clone sheet</button>
          <p>Cloned to: <strong data-testid="sheet-cloned-to">{{ clonedTo() }}</strong></p>
        </form>

        <form [formGroup]="asOfForm" (ngSubmit)="setAsOf()" aria-label="Show the sheet as of a date">
          <p>Parent sheet: <strong data-testid="sheet-parent">{{ sheet.parent ?? '' }}</strong></p>
          <p>As of: <strong data-testid="sheet-asof">{{ sheet.asOf ?? '' }}</strong></p>
          <label for="asof-date">Show as of</label>
          <input id="asof-date" type="date" data-testid="asof-date" formControlName="date" />
          <button type="submit" data-testid="asof-set" [disabled]="settingAsOf()">Set as of</button>
          <button type="button" data-testid="asof-clear" [disabled]="settingAsOf()" (click)="clearAsOf()">Clear as of</button>
          @if (asOfError(); as err) {
            <p role="alert" data-testid="asof-error">{{ err }}</p>
          }
        </form>

        <form [formGroup]="todayForm" (ngSubmit)="saveToday()" aria-label="Change the sheet's today">
          <label for="sheet-today-input">Change today</label>
          <input id="sheet-today-input" type="date" data-testid="sheet-today-input" formControlName="today" />
          <button type="submit" data-testid="sheet-today-save" [disabled]="savingToday()">Set today</button>
          @if (todayError(); as err) {
            <p role="alert" data-testid="sheet-error">{{ err }}</p>
          }
        </form>

        <app-rates />
        <app-grades />
        <app-settings />
        <app-delegations />
        <app-holidays />
        <app-void-reasons />
        <app-templates />
        <app-notes />
        <app-people />
        <app-duplicates />
        <app-search />
        <app-snapshot-compare />
        <app-audit />
        <app-activity />
      } @else {
        <p data-testid="sheet-none">Load a sheet to begin.</p>
      }
    } @else {
      <form [formGroup]="signInForm" (ngSubmit)="signIn()" aria-label="Sign in">
        <label for="signin-name">Your name</label>
        <input id="signin-name" data-testid="signin-name" formControlName="name" autocomplete="username" />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signInError(); as err) {
          <p role="alert" data-testid="signin-error">{{ err }}</p>
        }
      </form>
    }
  `,
})
export class Home {
  protected readonly session = inject(Session);
  protected readonly sheets = inject(Sheets);

  protected readonly signInForm = new FormGroup({
    name: new FormControl('', { nonNullable: true, validators: Validators.required }),
  });
  /** The signed-in user's locale, which decides how figures are shown to them. */
  protected readonly locales = LOCALES;
  protected readonly localeForm = new FormGroup({
    locale: new FormControl<Locale>('en', { nonNullable: true }),
  });
  protected readonly localeError = signal<string | null>(null);
  protected readonly savingLocale = signal(false);
  protected readonly sheetForm = new FormGroup({
    id: new FormControl('', { nonNullable: true, validators: Validators.required }),
  });
  protected readonly todayForm = new FormGroup({
    today: new FormControl('', { nonNullable: true, validators: Validators.required }),
  });
  /** The id to clone the sheet to. */
  protected readonly cloneForm = new FormGroup({
    to: new FormControl('', { nonNullable: true }),
  });
  /** The id the sheet was last cloned to from this screen; cleared while a clone runs. */
  protected readonly clonedTo = signal('');
  protected readonly cloning = signal(false);
  /** The date to show the sheet as of. */
  protected readonly asOfForm = new FormGroup({
    date: new FormControl('', { nonNullable: true }),
  });
  protected readonly signInError = signal<string | null>(null);
  protected readonly sheetError = signal<string | null>(null);
  protected readonly todayError = signal<string | null>(null);
  protected readonly loading = signal(false);
  protected readonly savingToday = signal(false);
  protected readonly archiving = signal(false);
  protected readonly asOfError = signal<string | null>(null);
  protected readonly settingAsOf = signal(false);

  constructor() {
    // An error is removed as soon as its form is changed.
    this.signInForm.valueChanges.subscribe(() => this.signInError.set(null));
    this.localeForm.valueChanges.subscribe(() => this.localeError.set(null));
    this.sheetForm.valueChanges.subscribe(() => this.sheetError.set(null));
    this.todayForm.valueChanges.subscribe(() => this.todayError.set(null));
    this.asOfForm.valueChanges.subscribe(() => this.asOfError.set(null));
    this.cloneForm.valueChanges.subscribe(() => this.todayError.set(null));
  }

  /** Clone the sheet to the id typed; a refusal shows on the sheet. */
  protected cloneSheet(): void {
    // A second press before the first has answered is ignored.
    if (this.cloning()) return;
    this.todayError.set(null);
    this.clonedTo.set('');
    const sheet = this.sheets.current();
    if (!sheet) return;
    const to = this.cloneForm.controls.to.value.trim();
    if (!/^[A-Za-z0-9._-]+$/.test(to)) {
      this.todayError.set('Type a sheet id to clone to.');
      return;
    }
    this.cloning.set(true);
    this.sheets.cloneTo(sheet.id, to).subscribe({
      next: (clone) => {
        this.cloning.set(false);
        this.clonedTo.set(clone.id);
      },
      error: () => {
        this.cloning.set(false);
        this.todayError.set('Could not clone the sheet to that id.');
      },
    });
  }

  /** Show the sheet as of the date typed: everything on screen as it stood at the end of that day. */
  protected setAsOf(): void {
    this.asOfError.set(null);
    const date = this.asOfForm.controls.date.value.trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      this.asOfError.set('Choose a date to show the sheet as of.');
      return;
    }
    this.showAsOf(date);
  }

  /** Show the sheet as it is now again. */
  protected clearAsOf(): void {
    this.asOfError.set(null);
    this.showAsOf(null);
  }

  private showAsOf(date: string | null): void {
    // A second press before the first has answered is ignored.
    if (this.settingAsOf()) return;
    const sheet = this.sheets.current();
    if (!sheet) return;
    this.settingAsOf.set(true);
    this.todayError.set(null);
    this.sheets.setAsOf(sheet.id, date).subscribe({
      next: (loaded) => {
        this.settingAsOf.set(false);
        this.todayForm.setValue({ today: loaded.today }, { emitEvent: false });
      },
      error: () => {
        this.settingAsOf.set(false);
        this.asOfError.set('Could not show the sheet as of that date.');
      },
    });
  }

  protected signIn(): void {
    this.signInError.set(null);
    const name = this.signInForm.controls.name.value.trim();
    if (!name) {
      this.signInError.set('Type your name to sign in.');
      return;
    }
    this.session.signIn(name).subscribe({
      next: (u) => this.localeForm.setValue({ locale: u.locale }, { emitEvent: false }),
      error: () => this.signInError.set('Could not sign in with that name.'),
    });
  }

  /** Save the locale chosen for the signed-in user. */
  protected saveLocale(): void {
    // A second submit before the first has answered is ignored.
    if (this.savingLocale()) return;
    this.localeError.set(null);
    this.savingLocale.set(true);
    this.session.setLocale(this.localeForm.controls.locale.value).subscribe({
      next: () => this.savingLocale.set(false),
      error: () => {
        this.savingLocale.set(false);
        this.localeError.set('Could not save your locale.');
      },
    });
  }

  protected loadSheet(): void {
    // A second submit before the first has answered is ignored.
    if (this.loading()) return;
   *  proof of each before it can be settled or approved; null when there are none. Not dated. */
  proofKinds: string | null;
  /** The sheet's default grade (A, B or C): the grade the quick-add bar gives a new person, and the one an imported
   *  line with a blank grade takes; null when it sets none (then A). Not dated. */
  defaultGrade: string | null;
  /** The grades retired on the sheet, in order: none can be given to a new person nor chosen in an edit; people on
   *  one keep it. Not dated. */
  retiredGrades: string[];
  /** The alert threshold (two decimals): a person whose due-total rises from at or below it to above it is alerted;
   *  null when it is off. Not dated. */
  alertThreshold: string | null;
  /** The id of the sheet's parent sheet: a grade with no rate in force on a date on this sheet takes its parent's
   *  (then its parent's parent's, up to three levels up); null when it has none. Not dated. */
  parent: string | null;
  /** Whether the sheet is archived: everything on it stays visible and every change to it is refused. */
  archived: boolean;
  /** The date (yyyy-mm-dd) the sheet is shown as of: it is as it stood at the end of that day, which stands in for
   *  its today; null when it is shown as it is now. */
  asOf: string | null;
  /** The sheet's entry date (yyyy-mm-dd): while set, a new claim given no date takes it in place of the sheet's
   *  today; null: off. Not dated. */
  entryDate: string | null;
}

/** The actions the permission matrix covers. */
export const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;
export type PermAction = (typeof PERM_ACTIONS)[number];

/** The roles that may take each action while its matrix entry is blank. */
export const STANDING_PERMISSIONS: Record<PermAction, string> = {
  open: 'clerk,steward', settle: 'clerk,steward', void: 'clerk,steward',
  reassign: 'steward', close: 'clerk,steward', reopen: 'steward',
};

/** A setting's value in force on a date (yyyy-mm-dd): the one recorded with the latest from-date on or before it;
 *  `start` (the sheet's starting value) before every from-date, or when it is none. */
export function settingOn(settings: readonly DatedSetting[], key: string, date: string, start: string): string {
  let inForce: DatedSetting | undefined;
  for (const s of settings) {
    if (s.key === key && (s.from === null || s.from <= date) && (inForce === undefined || inForce.from === null
        || (s.from !== null && s.from > inForce.from))) inForce = s;
  }
  return inForce?.value ?? start;
}

/** The grace days of a grade in force on a date (yyyy-mm-dd): a claim dated then whose person is of that grade
 *  then is overdue only once its due-by plus these is before the sheet's today; 0 when none is set. */
export function graceOn(settings: readonly DatedSetting[], grade: Grade, date: string): number {
  const value = settingOn(settings, `grace-${grade}`, date, '');
  return value === '' ? 0 : Number(value);
}

/** The terms a sheet has until they are changed. */
export const DEFAULT_TERMS = 14;

// The active sheet. Everything else in the app is kept per sheet; loading an id re-reads it from
// the store, and an id never loaded before starts an empty sheet.
@Injectable({ providedIn: 'root' })
export class Sheets {
  private readonly http = inject(HttpClient);
  private readonly active = signal<SheetView | null>(null);
  readonly current = this.active.asReadonly();
  /** The sheet as last (re)loaded: set on each load only, so changing its today re-reads nothing. */
  private readonly lastLoad = signal<SheetView | null>(null);
  readonly loaded = this.lastLoad.asReadonly();
  /** The date (yyyy-mm-dd) this screen shows the sheet as of; null: as it is now. Belongs to the screen, so loading a
   *  sheet leaves it as it is; every read then answers as the sheet stood at the end of it, and every change is refused. */
  private readonly asOfDate = signal<string | null>(null);
  readonly asOf = this.asOfDate.asReadonly();

  /** Show the sheet as of a date (null: as it is now), re-loading it so everything on screen is read that way. */
  setAsOf(id: string, asOf: string | null): Observable<SheetView> {
    this.asOfDate.set(asOf);
    return this.load(id);
  }

  load(id: string): Observable<SheetView> {
    return this.http
      .post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/load`, null)
      .pipe(
        tap((s) => {
          this.active.set(s);
          this.lastLoad.set(s);
        }),
      );
  }

  /** Note a settle batch just made on the active sheet as its last. */
  settleBatched(batch: number): void {
    this.active.update((s) => (s ? { ...s, settleBatch: batch } : s));
  }

  /** Archive the active sheet (a steward only). */
  archive(id: string): Observable<SheetView> {
    return this.http
      .post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/archive`, null)
      .pipe(tap((s) => this.active.set(s)));
  }

  /** Clone the active sheet to another id, never used before (a steward only); answers with the clone. */
  cloneTo(id: string, to: string): Observable<SheetView> {
    return this.http.post<SheetView>(`/api/sheets/${encodeURIComponent(id)}/clone`, { to });
  }

  /** Change the active sheet's today. */
  setToday(id: string, today: string): Observable<SheetView> {
    return this.http
      .put<SheetView>(`/api/sheets/${encodeURIComponent(id)}/today`, { today })
      .pipe(tap((s) => this.active.set(s)));
  }

