/** The sheet's pot (two decimals), cut among the members of each balanced pool that is a member of none; null means none. Not dated. */
@Column(name = "pot", precision = 14, scale = 2)
private BigDecimal pot;

/** The sheet's alert threshold (two decimals): a person whose due-total rises from at or below it to above it is
 *  alerted; null means off. Not dated. */
@Column(name = "alert_threshold", precision = 14, scale = 2)
private BigDecimal alertThreshold;

/** The id of the sheet's parent sheet, whose rates (then its parent's, up to three levels up) stand in for a
 *  grade with no rate in force on a date on this sheet; null means none. Not dated. */
@Column(name = "parent_id")
private String parentId;

/** The id of the sheet this one was cloned from, whose rate line (it, its parents, the sheet it was cloned from
 *  and so on) stands in for a grade with no rate in force on a date on this sheet nor its parents; null for a
 *  sheet that was not cloned. Not dated. */
@Column(name = "cloned_from")
private String clonedFrom;

/** The sheet's proof kinds, comma separated (receipt, photo): while set, a claim above the proof threshold needs
 *  a proof of each before it can be settled or approved; null means none. Not dated. */
@Column(name = "proof_kinds", length = 200)
private String proofKinds;

/** The sheet's default grade (A, B or C): the grade the quick-add bar gives a new person, and the one an
 *  imported line with a blank grade takes; null means A. Not dated. */
@Column(name = "default_grade", length = 1)
private String defaultGrade;

/** The grades retired on the sheet: none can be given to a new person nor chosen in an edit. Not dated. */
@ElementCollection(fetch = FetchType.EAGER)
@CollectionTable(name = "sheet_grade_retired", joinColumns = @JoinColumn(name = "sheet_id"))
@Column(name = "grade", nullable = false, length = 1)
private Set<String> retiredGrades = new TreeSet<>();

/** Whether the sheet is archived: everything on it stays visible and every change to it is refused. */
@Column(name = "archived", nullable = false)
private boolean archived;

protected Sheet() {
}

public Sheet(String id, String createdBy, Instant createdAt, LocalDate today) {
    this.id = id;
    this.createdBy = createdBy;
    this.createdAt = createdAt;
    this.today = today;
}

/** A copy of the sheet under another id, unsaved: its today, every setting (dated or not), its permission
 *  matrix, parent and last settle batch, naming this sheet as the one it was cloned from; its claim numbering
 *  starts afresh, and it is not archived. */
public Sheet copyTo(String id, String createdBy, Instant createdAt) {
    Sheet copy = new Sheet(id, createdBy, createdAt, today);
    settings.forEach(s -> copy.settings.add(new DatedSetting(s.getKey(), s.getFrom(), s.getValue())));
    copy.permissions.putAll(permissions);
    copy.policyDate = policyDate;
    copy.periodNumberingFrom = periodNumberingFrom;
    copy.entryDate = entryDate;
    copy.graceDays = graceDays;
    copy.escalateAfter = escalateAfter;
    copy.reviewSla = reviewSla;
    copy.maxOpen = maxOpen;
    copy.scoreMid = scoreMid;
    copy.scoreHigh = scoreHigh;
    copy.scoreLog = scoreLog;
    copy.fiscalStartMonth = fiscalStartMonth;
    copy.pot = pot;
    copy.alertThreshold = alertThreshold;
    copy.parentId = parentId;
    copy.clonedFrom = this.id;
    copy.proofKinds = proofKinds;
    copy.defaultGrade = defaultGrade;
    copy.retiredGrades.addAll(retiredGrades);
    copy.lastSettleBatch = lastSettleBatch;
    return copy;
}

public String getId() {
    return id;
}

public String getCreatedBy() {
    return createdBy;
}

public Instant getCreatedAt() {
    return createdAt;
}

